#include "stdlib/blas/base/dgemm.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"
#include "stdlib/blas/base/ddot.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"
#include <stdbool.h>
#include <stdint.h>

/**
 * Fills a matrix with zeros.
 *
 * @private
 * @param M        number of rows in the matrix
 * @param N        number of columns in the matrix
 * @param X        matrix to fill with zeros
 * @param strideX1 stride of the first dimension of `X`
 * @param strideX2 stride of the second dimension of `X`
 * @param offsetX  starting index for `X`
 */
static void zeros(const CBLAS_INT M, const CBLAS_INT N, double *X, const CBLAS_INT strideX1, const CBLAS_INT strideX2, const CBLAS_INT offsetX) {
	int64_t s[ 2 ];
	CBLAS_INT dx0;
	CBLAS_INT dx1;
	CBLAS_INT S0;
	CBLAS_INT S1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT ix;
	bool isrm;

	s[0] = strideX1;
	s[1] = strideX2;
	isrm = stdlib_ndarray_is_row_major( 2, s );
	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		S0 = N;
		S1 = M;
		dx0 = strideX2;
		dx1 = strideX1 - ( S0*strideX2 );
	} else { // CblasColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		S0 = M;
		S1 = N;
		dx0 = strideX1;
		dx1 = strideX2 - ( S0*strideX1 );
	}
	ix = offsetX;
	for ( i1 = 0; i1 < S1; i1++ ) {
		for ( i0 = 0; i0 < S0; i0++ ) {
			X[ ix ] = 0.0;
			ix += dx0;
		}
		ix += dx1;
	}
}

/**
 * Scales each element in a matrix by a scalar `β`.
 *
 * @private
 * @param M        number of rows in the matrix
 * @param N        number of columns in the matrix
 * @param beta     scalar constant
 * @param X        matrix to scale
 * @param strideX1 stride of the first dimension of `X`
 * @param strideX2 stride of the second dimension of `X`
 * @param offsetX  starting index for `X`
 */
static void scale( const CBLAS_INT M, const CBLAS_INT N, const double beta, double *X, const CBLAS_INT strideX1, const CBLAS_INT strideX2, const CBLAS_INT offsetX ) {
	int64_t s[ 2 ];
	CBLAS_INT dx0;
	CBLAS_INT dx1;
	CBLAS_INT S0;
	CBLAS_INT S1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT ix;
	bool isrm;

	s[0] = strideX1;
	s[1] = strideX2;
	isrm = stdlib_ndarray_is_row_major( 2, s );
	if ( isrm ) {
		// For row-major matrices, the last dimension has the fastest changing index...
		S0 = N;
		S1 = M;
		dx0 = strideX2;
		dx1 = strideX1 - ( S0*strideX2 );
	} else { // CblasColMajor
		// For column-major matrices, the first dimension has the fastest changing index...
		S0 = M;
		S1 = N;
		dx0 = strideX1;
		dx1 = strideX2 - ( S0*strideX1 );
	}
	ix = offsetX;
	for ( i1 = 0; i1 < S1; i1++ ) {
		for ( i0 = 0; i0 < S0; i0++ ) {
			X[ ix ] *= beta;
			ix += dx0;
		}
		ix += dx1;
	}
}

/**
 * Performs matrix multiplication using a naive algorithm which is cache-optimal when `A` is row-major and `B` is column-major.
 *
 * @private
 * @param M        number of rows in the matrix `op(A)` and number of rows in the matrix `C`
 * @param N        number of columns in the matrix `op(B)` and number of columns in the matrix `C`
 * @param K        number of columns in the matrix `op(A)` and number of rows in the matrix `op(B)`
 * @param alpha    scalar constant
 * @param A		   first matrix
 * @param strideA1 stride of the first dimension of `A`
 * @param strideA2 stride of the second dimension of `A`
 * @param offsetA  starting index for `A`
 * @param B		   second matrix
 * @param strideB1 stride of the first dimension of `B`
 * @param strideB2 stride of the second dimension of `B`
 * @param offsetB  starting index for `B`
 * @param C		   third matrix
 * @param strideC1 stride of the first dimension of `C`
 * @param strideC2 stride of the second dimension of `C`
 * @param offsetC  starting index for `C`
 */
static void naive( const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const double *B, const CBLAS_INT strideB1, const CBLAS_INT strideB2, const CBLAS_INT offsetB, double *C, const CBLAS_INT strideC1, const CBLAS_INT strideC2, const CBLAS_INT offsetC ) {
	CBLAS_INT da0;
	CBLAS_INT db0;
	CBLAS_INT dc0;
	CBLAS_INT dc1;
	CBLAS_INT S0;
	CBLAS_INT S1;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT ia;
	CBLAS_INT ib;
	CBLAS_INT ic;

	S0 = N;
	S1 = M;
	da0 = strideA2;
	db0 = strideB1;
	dc0 = strideC2;
	dc1 = strideC1 - ( S0*strideC2 );

	ic = offsetC;
	for ( i1 = 0; i1 < S1; i1++ ) {
		ia = offsetA + ( i1*strideA1 );
		for ( i0 = 0; i0 < S0; i0++ ) {
			ib = offsetB + ( i0*strideB2 );
			C[ ic ] += alpha * API_SUFFIX(c_ddot_ndarray)( K, A, da0, ia, B, db0, ib );
			ic += dc0;
		}
		ic += dc1;
	}
}

/**
 * Performs matrix multiplication using loop tiling.
 *
 * @private
 * @param M        number of rows in the matrix `op(A)` and number of rows in the matrix `C`
 * @param N        number of columns in the matrix `op(B)` and number of columns in the matrix `C`
 * @param K        number of columns in the matrix `op(A)` and number of rows in the matrix `op(B)`
 * @param alpha    scalar constant
 * @param A		   first matrix
 * @param strideA1 stride of the first dimension of `A`
 * @param strideA2 stride of the second dimension of `A`
 * @param offsetA  starting index for `A`
 * @param B		   second matrix
 * @param strideB1 stride of the first dimension of `B`
 * @param strideB2 stride of the second dimension of `B`
 * @param offsetB  starting index for `B`
 * @param C		   third matrix
 * @param strideC1 stride of the first dimension of `C`
 * @param strideC2 stride of the second dimension of `C`
 * @param offsetC  starting index for `C`
 */
static void blocked( const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const double *B, const CBLAS_INT strideB1, const CBLAS_INT strideB2, const CBLAS_INT offsetB, double *C, const CBLAS_INT strideC1, const CBLAS_INT strideC2, const CBLAS_INT offsetC ) {
	const CBLAS_INT bsize = 32; // TODO: move this to a header file
	CBLAS_INT da0;
	CBLAS_INT db0;
	CBLAS_INT dc0;
	CBLAS_INT dc1;
	CBLAS_INT oa1;
	CBLAS_INT ob0;
	CBLAS_INT oc0;
	CBLAS_INT oc1;
	CBLAS_INT S0;
	CBLAS_INT S1;
	CBLAS_INT s0;
	CBLAS_INT s1;
	CBLAS_INT sk;
	CBLAS_INT i0;
	CBLAS_INT i1;
	CBLAS_INT j0;
	CBLAS_INT j1;
	CBLAS_INT ia;
	CBLAS_INT ib;
	CBLAS_INT ic;
	CBLAS_INT oa;
	CBLAS_INT ob;
	CBLAS_INT k;

	// Note on variable naming convention: S#, da#, db#, dc#, i#, j# where # corresponds to the loop number, with `0` being the innermost loop...

	S0 = N;
	S1 = M;

	// Define increments for the innermost loop:
	da0 = strideA2;
	db0 = strideB1;
	dc0 = strideC2;

	// Iterate over blocks...
	for ( j1 = S1; j1 > 0; ) {
		if ( j1 < bsize ) {
			s1 = j1;
			j1 = 0;
		} else {
			s1 = bsize;
			j1 -= bsize;
		}
		oa1 = offsetA + ( j1*strideA1 );
		oc1 = offsetC + ( j1*strideC1 );
		for ( j0 = S0; j0 > 0; ) {
			if ( j0 < bsize ) {
				s0 = j0;
				j0 = 0;
			} else {
				s0 = bsize;
				j0 -= bsize;
			}
			ob0 = offsetB + ( j0*strideB2 );
			oc0 = oc1 + ( j0*strideC2 );      // index offset for `C` for the current block
			dc1 = strideC1 - ( s0*strideC2 ); // loop offset increment for `C`
			for ( k = K; k > 0; ) {
				if ( k < bsize ) {
					sk = k;
					k = 0;
				} else {
					sk = bsize;
					k -= bsize;
				}
				oa = oa1 + ( k*strideA2 );
				ob = ob0 + ( k*strideB1 );
				ic = oc0;
				for ( i1 = 0; i1 < s1; i1++ ) {
					ia = oa + ( i1*strideA1 );
					for ( i0 = 0; i0 < s0; i0++ ) {
						ib = ob + ( i0*strideB2 );
						C[ ic ] += alpha * API_SUFFIX(c_ddot_ndarray)( sk, A, da0, ia, B, db0, ib );
						ic += dc0;
					}
					ic += dc1;
				}
			}
		}
	}
}

/**
* Performs the matrix-matrix operation `C = α*op(A)*op(B) + β*C` where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `α` and `β` are scalars, `A`, `B`, and `C` are matrices, with `op(A)` an `M` by `K` matrix, `op(B)` a `K` by `N` matrix, and `C` an `M` by `N` matrix.
*
* @param transA   specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param transB   specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param M        number of rows in the matrix `op(A)` and number of rows in the matrix `C`
* @param N        number of columns in the matrix `op(B)` and number of columns in the matrix `C`
* @param K        number of columns in the matrix `op(A)` and number of rows in the matrix `op(B)`
* @param alpha    scalar constant
* @param A		  first matrix
* @param strideA1 stride of the first dimension of `A`
* @param strideA2 stride of the second dimension of `A`
* @param offsetA  starting index for `A`
* @param B		  second matrix
* @param strideB1 stride of the first dimension of `B`
* @param strideB2 stride of the second dimension of `B`
* @param offsetB  starting index for `B`
* @param beta     scalar constant
* @param C		  third matrix
* @param strideC1 stride of the first dimension of `C`
* @param strideC2 stride of the second dimension of `C`
* @param offsetC  starting index for `C`
*/
void API_SUFFIX(c_dgemm_ndarray)( const CBLAS_TRANSPOSE transA, const CBLAS_TRANSPOSE transB, const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT strideA1, const CBLAS_INT strideA2, const CBLAS_INT offsetA, const double *B, const CBLAS_INT strideB1, const CBLAS_INT strideB2, const CBLAS_INT offsetB, const double beta, double *C, const CBLAS_INT strideC1, const CBLAS_INT strideC2, const CBLAS_INT offsetC ) {
	int64_t sa[ 2 ];
	int64_t sb[ 2 ];
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT sb1;
	CBLAS_INT sb2;
	bool isrma;
	bool isrmb;

	// Note on variable naming convention: da#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	// Perform input argument validation...
	if ( transA != CblasTrans && transA != CblasConjTrans && transA != CblasNoTrans ) {
		c_xerbla( 1, "c_dgemm_ndarray", "Error: invalid argument. First argument must be a valid transpose operation. Value: `%d`.", transA );
		return;
	}
	if ( transB != CblasTrans && transB != CblasConjTrans && transB != CblasNoTrans ) {
		c_xerbla( 2, "c_dgemm_ndarray", "Error: invalid argument. Second argument must be a valid transpose operation. Value: `%d`.", transB );
		return;
	}
	if ( M < 0 ) {
		c_xerbla( 3, "c_dgemm_ndarray", "Error: invalid argument. Third argument must be a nonnegative integer. Value: `%d`.", M );
		return;
	}
	if( N < 0 ) {
		c_xerbla( 4, "c_dgemm_ndarray", "Error: invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( K < 0 ) {
		c_xerbla( 5, "c_dgemm_ndarray", "Error: invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.", K );
		return;
	}

	// Check whether we can avoid computation altogether...
if ( M == 0 || N == 0 || ( ( ( alpha == 0.0 ) || ( K == 0 ) ) && ( beta == 1.0) ) ) {
		return;
	}

	// Form: C = β⋅C
	if ( beta == 0.0 ) {
		zeros( M, N, C, strideC1, strideC2, offsetC );
	} else if ( beta != 1.0 ) {
		scale( M, N, beta, C, strideC1, strideC2, offsetC );
	}
	// Check whether we can early return
	if ( alpha == 0.0 ) {
		return;
	}

	sa[ 0 ] = strideA1;
	sa[ 1 ] = strideA2;
	sb[ 0 ] = strideB1;
	sb[ 1 ] = strideB2;
	isrma = stdlib_ndarray_is_row_major( 2, sa );
	isrmb = stdlib_ndarray_is_row_major( 2, sb );

	// Check whether we can avoid loop tiling and simply use the "naive" (cache-optimal) algorithm for performing matrix multiplication...
	if ( isrma ) {
		if ( transA == CblasNoTrans ) {
			if ( !isrmb && transB == CblasNoTrans ) {
				// Form: C = α⋅A⋅B + C
				naive( M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB1, strideB2, offsetB, C, strideC1, strideC2, offsetC );
				return;
			}
			if ( isrmb && transB != CblasNoTrans ) {
				// Form: C = α⋅A⋅B^T + C
				naive( M, N, K, alpha, A, strideA1, strideA2, offsetA, B, strideB2, strideB1, offsetB, C, strideC1, strideC2, offsetC );
				return;
			}
		}
	} else if ( transA != CblasNoTrans ) {
		if ( isrmb && transB != CblasNoTrans ) {
			// Form: C = α⋅A^T⋅B^T + C
			naive( M, N, K, alpha, A, strideA2, strideA1, offsetA, B, strideB2, strideB1, offsetB, C, strideC1, strideC2, offsetC );
			return;
		}
		if ( !isrmb && transB == CblasNoTrans ) {
			// Form: C = α⋅A^T⋅B + C
			naive( M, N, K, alpha, A, strideA2, strideA1, offsetA, B, strideB1, strideB2, offsetB, C, strideC1, strideC2, offsetC );
			return;
		}
	}
	// Swap strides to perform transposes...
	if ( transA != CblasNoTrans ) {
		sa1 = strideA2;
		sa2 = strideA1;
	} else {
		sa1 = strideA1;
		sa2 = strideA2;
	}
	if ( transB != CblasNoTrans ) {
		sb1 = strideB2;
		sb2 = strideB1;
	} else {
		sb1 = strideB1;
		sb2 = strideB2;
	}
	// Perform loop tiling to promote cache locality
	blocked( M, N, K, alpha, A, sa1, sa2, offsetA, B, sb1, sb2, offsetB, C, strideC1, strideC2, offsetC );
	return;
}
